"use client";
import { ArtifactCard as SharedArtifactCard } from "@ui/artifact-card";
import { resolveArtifactLabels } from "@ui/artifact-panel/labels";
import { artifactReviewStatus, artifactSizeText, safeArtifactUrl } from "@ui/artifact-panel/utils";
import type { ArtifactCardProps } from "./chat-workspace-types";
/** Compatibility adapter for full workspace resources and their review rules. */
export function ArtifactCard({ labels: overrides, locale, ...props }: ArtifactCardProps) {
    const labels = resolveArtifactLabels(locale, overrides);
    return <SharedArtifactCard {...props} labels={labels} locale={locale} getReviewStatus={artifactReviewStatus} getDescription={(resource) => resource.kind === "url"
            ? safeArtifactUrl(resource.url, true) ?? labels.unavailableUrl
            : artifactSizeText(resource, locale)}/>;
}

import type { ArtifactResource } from "./chat-workspace-types";
/** Local fixtures. URL/image hosts may replace these two asset addresses. */
export function createChatWorkspaceDemoResources(locale = "en", assetBase = "/demos/chat-workspace"): ArtifactResource[] {
    const zh = locale.toLowerCase().startsWith("zh");
    return [
        {
            id: "theme", version: "1", kind: "code", name: "theme.ts", path: "src/lib/theme.ts", messageId: "result", review: "pending",
            previousContent: `export type Theme = "light" | "dark";

export function readTheme(): Theme {
  return "light";
}

export function applyTheme(theme: Theme) {
  document.documentElement.classList.toggle("dark", theme === "dark");
}
`,
            content: `export type Theme = "light" | "dark" | "system";

const storageKey = "workspace-theme";

export function readTheme(): Theme {
  if (typeof window === "undefined") return "system";
  const saved = localStorage.getItem(storageKey);
  return saved === "light" || saved === "dark" ? saved : "system";
}

export function applyTheme(theme: Theme) {
  const dark = theme === "system"
    ? matchMedia("(prefers-color-scheme: dark)").matches
    : theme === "dark";
  document.documentElement.classList.toggle("dark", dark);
  localStorage.setItem(storageKey, theme);
}
`,
        },
        {
            id: "readme", version: "1", kind: "markdown", name: "README.md", path: "docs/README.md", messageId: "result", review: "pending",
            previousContent: "# Appearance

Choose a light or dark theme.
",
            content: zh ? `# 外观设置

让工作区跟随你的习惯。现在支持 **浅色、深色、跟随系统** 三种主题。

## 使用方式

1. 打开「设置 → 外观」。
2. 选择喜欢的主题。
3. 选择会保存在当前浏览器，下次访问自动应用。

| 主题 | 行为 |
| --- | --- |
| 浅色 | 始终使用浅色外观 |
| 深色 | 始终使用深色外观 |
| 跟随系统 | 打开页面时读取系统偏好 |

## 验收清单

- [x] 主题切换即时生效
- [x] 刷新后保留选择
- [x] 首次访问默认跟随系统

> 右侧可以预览文档、阅读源码，也可以检查本次变更。
` : `# Appearance

A workspace that feels like yours. Choose **Light, Dark or System** and keep your preference between visits.

## Getting started

1. Open **Settings → Appearance**.
2. Choose your preferred theme.
3. Your choice is saved in this browser and restored on the next visit.

| Theme | Behavior |
| --- | --- |
| Light | Always use the light appearance |
| Dark | Always use the dark appearance |
| System | Read your system preference when the page opens |

## Acceptance checklist

- [x] Theme changes apply immediately
- [x] Your choice survives a refresh
- [x] First visits default to the system preference

> Preview the document, read its source, or review the changes in this panel.
`,
        },
        { id: "design", version: "1", kind: "image", name: "appearance.svg", path: "design/appearance.svg", url: `${assetBase}/appearance.svg`, size: 2883, alt: zh ? "外观设置设计稿，展示浅色、深色与跟随系统三种选项" : "Appearance design showing light, dark and system options", messageId: "result" },
        { id: "website", version: "1", kind: "url", name: zh ? "页面预览" : "Live preview", url: `${assetBase}/preview.html`, messageId: "result" },
        { id: "archive", version: "1", kind: "file", name: "release-notes.zip", mimeType: "application/zip", size: 24576, messageId: "result" },
    ];
}

import type { HTMLAttributes, ReactNode } from "react";
import type { ChatThreadProps } from "@ui/chat-thread";
import type { ResizablePanelGroupProps } from "@ui/resizable";
import type { ArtifactResource, ArtifactLabels } from "@ui/artifact-panel";
export type { ArtifactReviewStatus, ArtifactReviewDecision, ArtifactView, ArtifactResource, ArtifactLabels, ArtifactPanelProps } from "@ui/artifact-panel";
export interface ArtifactCardProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
    resources: readonly ArtifactResource[];
    title?: string;
    onOpen: (resource: ArtifactResource) => void;
    labels?: Partial<ArtifactLabels>;
    locale?: string;
}
export interface ChatWorkspaceProps extends ChatThreadProps {
    /** Usually ArtifactPanel; this slot can also contain a host-owned viewer. */
    artifacts: ReactNode;
    title?: string;
    /** Host-owned session actions, shown beside the content pane controls. */
    headerActions?: ReactNode;
    panelOpen?: boolean;
    defaultPanelOpen?: boolean;
    onPanelOpenChange?: (open: boolean) => void;
    activePane?: "chat" | "artifacts";
    defaultActivePane?: "chat" | "artifacts";
    onActivePaneChange?: (pane: "chat" | "artifacts") => void;
    chatDefaultSize?: string;
    chatMinSize?: string;
    artifactMinSize?: string;
    onLayoutChanged?: ResizablePanelGroupProps["onLayoutChanged"];
    workspaceLabels?: Partial<ArtifactLabels>;
}

"use client";
import { useEffect, useId, useRef, useState, type Ref } from "react";
import { ChatThread } from "@ui/chat-thread";
import { Button } from "@ui/button";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup, type ResizablePanelProps } from "@ui/resizable";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { resolveArtifactLabels } from "@ui/artifact-panel/labels";
import type { ChatWorkspaceProps } from "./chat-workspace-types";
type PanelHandle = NonNullable<ResizablePanelProps["panelRef"]> extends Ref<infer T> ? T : never;
export function ChatWorkspace({ artifacts, title, headerActions, panelOpen, defaultPanelOpen = true, onPanelOpenChange, activePane, defaultActivePane = "chat", onActivePaneChange, chatDefaultSize = "38%", chatMinSize = "280px", artifactMinSize = "320px", onLayoutChanged, workspaceLabels, className, ...threadProps }: ChatWorkspaceProps) {
    const labels = resolveArtifactLabels(threadProps.locale, workspaceLabels);
    const [internalOpen, setInternalOpen] = useState(defaultPanelOpen);
    const [internalPane, setInternalPane] = useState(defaultActivePane);
    const open = panelOpen ?? internalOpen;
    const pane = activePane ?? internalPane;
    const [wide, setWide] = useState(true);
    const root = useRef<HTMLDivElement>(null);
    const chat = useRef<PanelHandle>(null);
    const desktopSize = useRef(chatDefaultSize);
    const chatId = useId();
    const artifactId = useId();
    const CollapseIcon = useIcon("layout-align-right");
    const ExpandIcon = useIcon("layout-align-left");
    const PanelIcon = open ? CollapseIcon : ExpandIcon;
    useEffect(() => {
        const node = root.current;
        if (!node)
            return;
        const observer = new ResizeObserver(() => setWide(node.clientWidth >= 760));
        setWide(node.clientWidth >= 760);
        observer.observe(node);
        return () => observer.disconnect();
    }, []);
    useEffect(() => {
        chat.current?.resize(wide ? open ? desktopSize.current : "100%" : open && pane === "artifacts" ? "0%" : "100%");
    }, [wide, open, pane]);
    const setOpen = (next: boolean) => {
        if (panelOpen === undefined)
            setInternalOpen(next);
        onPanelOpenChange?.(next);
    };
    const setPane = (next: "chat" | "artifacts") => {
        if (activePane === undefined)
            setInternalPane(next);
        onActivePaneChange?.(next);
        if (next === "artifacts")
            setOpen(true);
    };
    const hideChat = !wide && open && pane === "artifacts";
    const hideArtifacts = !open || (!wide && pane === "chat");
    useEffect(() => {
        if (!hideChat)
            return;
        const frame = requestAnimationFrame(() => root.current?.querySelector<HTMLElement>('[data-slot="artifact-panel"] [role="tab"][aria-selected="true"]')?.focus());
        return () => cancelAnimationFrame(frame);
    }, [hideChat]);
    return <div ref={root} data-block="chat-workspace-01" data-layout={wide ? "horizontal" : "single"} className={cn("flex size-full min-h-0 min-w-0 flex-col overflow-hidden bg-surface-floating text-fg-default", className)}>
    <div className="flex shrink-0 items-center justify-between gap-3 border-b-hairline border-border px-4 py-2">
      <span data-slot="workspace-title" className="min-w-0 flex-1 truncate text-body font-medium" title={title ?? labels.workspace}>{title ?? labels.workspace}</span>
      <div className="flex shrink-0 items-center gap-1">
      {headerActions}
      {wide ? <Button variant="ghost" iconOnly aria-label={open ? labels.hidePanel : labels.showPanel} aria-expanded={open} aria-controls={artifactId} onClick={() => setOpen(!open)}><PanelIcon aria-hidden/></Button> :
            <div className="flex items-center gap-1">
          <Button variant="ghost" size="sm" active={!hideChat} aria-pressed={!hideChat} onClick={() => setPane("chat")}>{labels.conversation}</Button>
          <Button variant="ghost" size="sm" active={hideChat} aria-pressed={hideChat} onClick={() => setPane("artifacts")}>{labels.preview}</Button>
        </div>}
      </div>
    </div>
    <ResizablePanelGroup orientation="horizontal" disabled={!wide || !open} aria-label={labels.workspace} className="min-h-0 flex-1" onLayoutChanged={(layout, meta) => {
            if (meta.isUserInteraction && wide && open && layout[chatId] > 10 && layout[chatId] < 90)
                desktopSize.current = `${layout[chatId]}%`;
            onLayoutChanged?.(layout, meta);
        }}>
      <ResizablePanel id={chatId} panelRef={chat} defaultSize={chatDefaultSize} minSize={wide && open ? chatMinSize : "0%"} className={cn("overflow-hidden", hideChat && "invisible")} inert={hideChat} aria-hidden={hideChat || undefined}>
        <ChatThread {...threadProps}/>
      </ResizablePanel>
      <ResizableHandle withHandle aria-label={labels.resize} className={(!wide || !open) ? "hidden" : undefined}/>
      <ResizablePanel id={artifactId} minSize={wide && open ? artifactMinSize : "0%"} className={cn("overflow-hidden", hideArtifacts && "invisible")} inert={hideArtifacts} aria-hidden={hideArtifacts || undefined}>
        {artifacts}
      </ResizablePanel>
    </ResizablePanelGroup>
  </div>;
}

export { ChatWorkspace } from "./chat-workspace";
export { ArtifactPanel } from "./artifact-panel";
export { ArtifactCard } from "./artifact-card";
export { artifactEnLabels, artifactZhLabels } from "./artifact-labels";
export { createChatWorkspaceDemoResources } from "./chat-workspace-demo-data";
export { getPendingReviewResources } from "./artifact-utils";
export type { ArtifactCardProps, ArtifactLabels, ArtifactPanelProps, ArtifactResource, ArtifactReviewDecision, ArtifactReviewStatus, ArtifactView, ChatWorkspaceProps } from "./chat-workspace-types";
